import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import "core-js/modules/es.iterator.reduce.js";
import "core-js/modules/es.iterator.some.js";
import { db } from '../firebase/config';
import { collection, getDocs } from 'firebase/firestore';
export default {
  name: 'MainComponent',
  data() {
    return {
      products: [],
      showQuickView: false,
      selectedProduct: null,
      currentFilter: 'all',
      searchQuery: '',
      showDiscountsModal: false,
      cartOpen: false,
      cartItems: [],
      isMobile: false,
      categoryScrollPositions: {},
      filteredScrollPosition: 0
    };
  },
  mounted() {
    this.loadProducts();
    this.loadCart();
    this.checkMobile();
    window.addEventListener('set-category', this.onSetCategory);
    window.addEventListener('set-search', this.onSetSearch);
    window.addEventListener('toggle-cart', this.onToggleCart);
    window.addEventListener('storage', this.loadCart);
    window.addEventListener('resize', this.checkMobile);
  },
  beforeUnmount() {
    window.removeEventListener('set-category', this.onSetCategory);
    window.removeEventListener('set-search', this.onSetSearch);
    window.removeEventListener('toggle-cart', this.onToggleCart);
    window.removeEventListener('storage', this.loadCart);
    window.removeEventListener('resize', this.checkMobile);
  },
  computed: {
    cartTotal() {
      return this.cartItems.reduce((total, item) => {
        const price = this.discountedPrice(item);
        const quantity = item.quantity || 1;
        return total + price * quantity;
      }, 0);
    },
    visibleProducts() {
      const q = (this.searchQuery || '').toLowerCase().trim();
      return this.products.filter(p => {
        const matchesCategory = this.currentFilter === 'all' || (p.author || p.category || '').toLowerCase() === this.currentFilter;
        const matchesQuery = !q || [p.title, p.name, p.author, p.category, p.description].filter(Boolean).some(v => String(v).toLowerCase().includes(q));
        return matchesCategory && matchesQuery;
      });
    },
    discountedProducts() {
      return this.products.filter(p => Number(p.discount || 0) > 0);
    },
    categories() {
      const categoryMap = {
        'hombre': {
          name: 'hombre',
          label: 'Hombre',
          products: []
        },
        'mujer': {
          name: 'mujer',
          label: 'Mujer',
          products: []
        },
        'accesorios': {
          name: 'accesorios',
          label: 'Accesorios',
          products: []
        }
      };
      const q = (this.searchQuery || '').toLowerCase().trim();
      this.products.forEach(p => {
        const category = (p.author || p.category || '').toLowerCase();
        const matchesQuery = !q || [p.title, p.name, p.author, p.category, p.description].filter(Boolean).some(v => String(v).toLowerCase().includes(q));
        if (matchesQuery && categoryMap[category]) {
          categoryMap[category].products.push(p);
        }
      });
      return Object.values(categoryMap).filter(cat => cat.products.length > 0);
    }
  },
  methods: {
    async loadProducts() {
      try {
        // Cargar productos desde Firestore (colección: 'products')
        const col = collection(db, 'products');
        const snapshot = await getDocs(col);
        if (!snapshot.empty) {
          this.products = snapshot.docs.map(d => {
            const p = d.data();
            return {
              id: d.id,
              title: p.name || p.title || 'Sin título',
              author: p.category || 'Desconocido',
              description: p.description || '',
              price: typeof p.price === 'number' ? p.price : parseFloat(p.price) || 0,
              image: p.image || null,
              stock: Number(p.stock ?? 0),
              discount: Number(p.discount ?? 0)
            };
          });
          return;
        }
        // Si no hay documentos en Firestore, usar respaldo local si existe
        const savedAdmin = localStorage.getItem('admin_products');
        if (savedAdmin) {
          const items = JSON.parse(savedAdmin);
          this.products = items.map(p => ({
            id: String(p.id),
            title: p.name,
            author: p.category,
            description: p.description || '',
            price: Number(p.price) || 0,
            image: p.image || null,
            stock: Number(p.stock ?? 0),
            discount: Number(p.discount ?? 0)
          }));
        } else {
          this.products = [];
        }
      } catch (err) {
        console.error('Error cargando productos en MainComponent:', err);
        // Fallback a localStorage si falla la conexión a Firestore
        try {
          const savedAdmin = localStorage.getItem('admin_products');
          if (savedAdmin) {
            const items = JSON.parse(savedAdmin);
            this.products = items.map(p => ({
              id: String(p.id),
              title: p.name,
              author: p.category,
              description: p.description || '',
              price: Number(p.price) || 0,
              image: p.image || null,
              stock: Number(p.stock ?? 0),
              discount: Number(p.discount ?? 0)
            }));
          } else {
            this.products = [];
          }
        } catch (fallbackErr) {
          console.error('Error en fallback:', fallbackErr);
          this.products = [];
        }
      }
    },
    openDiscountsModal() {
      this.showDiscountsModal = true;
    },
    closeDiscountsModal() {
      this.showDiscountsModal = false;
    },
    setFilter(f) {
      this.currentFilter = f;
      // Reset scroll positions when filter changes
      this.categoryScrollPositions = {};
      this.filteredScrollPosition = 0;
    },
    onSetCategory(e) {
      this.currentFilter = e.detail || 'all';
      const el = document.querySelectorAll('.filter-btn');
      if (el && el.length) {
        // visual state handled by :class, nothing to do
      }
    },
    onSetSearch(e) {
      this.searchQuery = e.detail || '';
    },
    onToggleCart() {
      this.cartOpen = !this.cartOpen;
    },
    closeCart() {
      this.cartOpen = false;
    },
    loadCart() {
      try {
        const saved = localStorage.getItem('cart');
        this.cartItems = saved ? JSON.parse(saved) : [];
      } catch (err) {
        console.error('Error cargando carrito:', err);
        this.cartItems = [];
      }
    },
    increaseQuantity(productId) {
      const item = this.cartItems.find(i => i.id === productId);
      if (item) {
        item.quantity = (item.quantity || 1) + 1;
        this.saveCart();
      }
    },
    decreaseQuantity(productId) {
      const item = this.cartItems.find(i => i.id === productId);
      if (item) {
        if (item.quantity > 1) {
          item.quantity = item.quantity - 1;
        } else {
          this.removeFromCart(productId);
          return;
        }
        this.saveCart();
      }
    },
    removeFromCart(productId) {
      this.cartItems = this.cartItems.filter(i => i.id !== productId);
      this.saveCart();
    },
    saveCart() {
      try {
        localStorage.setItem('cart', JSON.stringify(this.cartItems));
        window.dispatchEvent(new Event('storage'));
      } catch (err) {
        console.error('Error guardando carrito:', err);
      }
    },
    proceedToCheckout() {
      alert('Funcionalidad de pago próximamente disponible');
    },
    formatPrice(val) {
      if (typeof val !== 'number') return val;
      return val.toFixed(2);
    },
    getPlaceholder() {
      return 'data:image/svg+xml;base64,';
    },
    discountedPrice(p) {
      const d = Number(p.discount || 0);
      if (!d) return Number(p.price || 0);
      return Number(p.price || 0) * (1 - d / 100);
    },
    viewProduct() {
      this.$router.push({
        name: 'Products'
      });
    },
    openQuickView(p) {
      this.selectedProduct = p;
      this.showQuickView = true;
    },
    closeQuickView() {
      this.showQuickView = false;
      this.selectedProduct = null;
    },
    addToCart(product) {
      try {
        const productName = product.title || product.name;
        const idx = this.cartItems.findIndex(i => i.id === product.id);
        if (idx > -1) {
          this.cartItems[idx].quantity = (this.cartItems[idx].quantity || 1) + 1;
        } else {
          this.cartItems.push({
            ...product,
            quantity: 1
          });
        }
        this.saveCart();

        // Mostrar notificación de producto agregado
        window.dispatchEvent(new CustomEvent('show-notification', {
          detail: {
            message: `"${productName}" agregado al carrito`,
            type: 'success',
            duration: 2500
          }
        }));

        // Open cart sidebar when item is added
        this.cartOpen = true;
        console.log(`"${productName}" agregado al carrito`);
      } catch (err) {
        console.error('Error al agregar al carrito:', err);
        window.dispatchEvent(new CustomEvent('show-notification', {
          detail: {
            message: 'Error al agregar producto al carrito',
            type: 'error',
            duration: 3000
          }
        }));
      }
    },
    checkMobile() {
      this.isMobile = window.innerWidth <= 768;
      // Force reactivity update
      this.$forceUpdate();
    },
    scrollCategory(categoryName, direction) {
      if (!this.categoryScrollPositions[categoryName]) {
        this.categoryScrollPositions[categoryName] = 0;
      }
      const cardWidth = 320 + 12; // card width + gap
      const scrollAmount = cardWidth * 2; // scroll 2 cards at a time

      if (direction === 'next') {
        const category = this.categories.find(c => c.name === categoryName);
        if (category) {
          const maxScroll = Math.max(0, (category.products.length - 1) * cardWidth - window.innerWidth + 100);
          this.categoryScrollPositions[categoryName] = Math.min(this.categoryScrollPositions[categoryName] + scrollAmount, maxScroll);
        }
      } else {
        this.categoryScrollPositions[categoryName] = Math.max(0, this.categoryScrollPositions[categoryName] - scrollAmount);
      }
    },
    scrollFiltered(direction) {
      const cardWidth = 320 + 12;
      const scrollAmount = cardWidth * 2;
      if (direction === 'next') {
        const maxScroll = Math.max(0, (this.visibleProducts.length - 1) * cardWidth - window.innerWidth + 100);
        this.filteredScrollPosition = Math.min(this.filteredScrollPosition + scrollAmount, maxScroll);
      } else {
        this.filteredScrollPosition = Math.max(0, this.filteredScrollPosition - scrollAmount);
      }
    }
  }
};
